export interface INicknameConfig {
    userId: string | number;
    sessionToken: string;
    operatorId: string;
    endpoint: string;
    minCharacters?: number;
    maxCharacters?: number;
    cMIdentifier?: string;
    isVisible: boolean;
}

export interface INicknameStateConfig {
    userId: string;
    sessionToken: string;
    operatorId: string;
    endpoint: string;
    minCharacters: number;
    maxCharacters: number;
    isVisible: boolean;
    cMIdentifier: string;
}

export interface INicknameState {
    config: INicknameStateConfig;
    requirements: IRequirementsState
    nickname: string;
    nicknameAccepted: boolean;
    isSubmitting: boolean;
    error: IErrorState;
    resetErrorState(): void;
}

export interface IRequirementsState {
    length: boolean;
    startingCharacter: boolean;
    alphaNumeric: boolean;
}

export interface IErrorState {
    hasErrored: boolean;
    errorCode: number;
    errors: IError[];
}

export interface IError {
    name: string;
    description: string;
}
